<script setup>
import PagedRecords from './PagedRecords.vue';
import ListPager from './ListPager.vue';
import {s,canEdit,canAdmin,api,loadSources,sourceEnabled,resolveConflict,run,stageFile,stageSheet,aiMapping,previewData,commitData,toggleSync,sync,dateText,number} from './store';
</script><template><section class="stack"><div v-if="!canEdit" class="notice">Bạn có quyền xem. Liên hệ Admin sự kiện để được cấp quyền chỉnh sửa.</div><div class="card stack"><div class="toolbar"><h3>Nguồn dữ liệu</h3><MButton v-if="canEdit&&s.eventSources.some(v=>v.enabled)" variant="secondary" :loading="s.busy" @click="run(sync)">Đồng bộ ngay</MButton></div><p v-if="!s.eventSources.length" class="muted">Chưa có nguồn dữ liệu.</p><PagedRecords v-else :rows="s.eventSources" v-slot="{rows}"><article v-for="source in rows" :key="source.id" class="source-entry"><div class="toolbar"><strong>{{source.label}}</strong><span>{{source.mode==='auto'?'Theo từng dòng':source.mode==='online'?'Online':'Offline'}}</span></div><div class="row"><span class="muted">{{source.kind==='sheet'?'Google Sheet':'File'}} · {{dateText(source.synced_at)}}</span><MCheckbox v-if="source.kind==='sheet'" :model-value="source.enabled" :disabled="!canAdmin||s.busy" label="Tự đồng bộ" @update:model-value="run(()=>sourceEnabled(source,$event))"/></div><p v-if="source.error" class="error">{{source.error}}</p></article></PagedRecords></div>
<div v-if="s.conflicts?.total&&canAdmin" class="card stack"><h3>Khách cần đối chiếu ({{s.conflicts.total}})</h3><p class="muted">Các dòng này chưa cộng vào báo cáo. Chọn hồ sơ cần cập nhật hoặc xác nhận là khách khác.</p><article v-for="item in s.conflicts.rows" :key="item.id" class="source-entry stack"><strong>{{item.data.name||'Chưa có tên'}} · {{item.data.phone||item.data.email||'—'}}</strong><p>{{item.reason}}</p><MButton v-for="candidate in item.candidates" :key="candidate.id" variant="secondary" :loading="s.busy" @click="run(()=>resolveConflict(item,candidate.id))">Cập nhật {{candidate.data.name||'khách'}} · {{candidate.data.phone||candidate.data.email}}</MButton><MButton variant="secondary" :loading="s.busy" @click="run(()=>resolveConflict(item,null))">Là khách khác — tạo hồ sơ riêng</MButton></article><ListPager :page="s.conflicts.page" :page-size="s.conflicts.pageSize" :total="s.conflicts.total" @update:page-size="s.conflicts.pageSize=$event" @update:page="run(async()=>s.conflicts=await api('/api/events/'+s.event.id+'/conflicts?page='+$event+'&pageSize='+s.conflicts.pageSize))"/></div>
<div v-if="canEdit" class="card stack"><h3>Nhập dữ liệu mới</h3><p class="muted">Mỗi nguồn được cập nhật riêng. Nhập lại không xóa khách hay ghi đè lịch sử liên hệ. Trường thiếu được để trống.</p><div class="grid-form"><label class="field">Nhập vào nhóm<MSelect v-model="s.importMode" :options="[{value:'auto',label:'Theo từng dòng — thiếu thì Chưa xác định'},{value:'online',label:'Online'},{value:'offline',label:'Offline'}]"/></label><label class="field">Loại danh sách<MSelect v-model="s.registrationStatus" :options="[{value:'registered',label:'Khách đã đăng ký'},{value:'invited',label:'Danh sách mời — chưa đăng ký'}]"/></label></div><div class="grid-form"><label class="field">Tên tab (* để đọc tất cả các phòng / nhóm)<MInput v-model="s.sheetName" /></label><label class="field">Dòng tiêu đề (0 để tự nhận diện)<MInput v-model="s.headerRow" /></label></div><MUpload accept=".xlsx,.csv" :multiple="false" :max-size-m-b="10" :disabled="s.busy" label="Chọn file Excel hoặc CSV" @select-files="run(()=>stageFile($event))" @oversized="s.error='File tối đa 10 MB.'" /><label v-if="canAdmin" class="field">Link Google Sheet<MInput v-model="s.sheetUrl" placeholder="https://docs.google.com/spreadsheets/..." /></label><div v-if="canAdmin" class="row justify-end"><MButton variant="primary" :loading="s.busy" @click="run(stageSheet)">Nhập và tổng hợp</MButton></div></div>
<div v-if="s.stage&&canEdit" class="card stack"><div class="toolbar"><h3>Ghép cột · {{number(s.stage.count)}} dòng</h3><MButton variant="secondary" :loading="s.busy" @click="run(aiMapping)">Gợi ý bằng Gemini</MButton></div><p class="muted">{{s.stage.discovery?.notice||'Đã nhận diện các cột nguồn khách.'}}</p><div class="grid-form"><label v-for="(label,key) in s.user.fields" :key="key" class="field">{{label}}<MCombobox v-model="s.mapping[key]" :options="[{label:'Không có cột',value:''},...s.stage.headers.map(h=>({value:h,label:h}))]" @change="s.preview=null" /></label></div><label class="field">Các cột dùng lọc nguồn, nhân viên (tối đa 12)<MCombobox v-model="s.sourceColumns" multiple :options="s.stage.headers.map(h=>({value:h,label:h}))" @change="s.preview=null" /></label><MCheckbox v-model="s.autoSync" label="Tự đồng bộ nếu nguồn là Google Sheet"/><div v-if="s.preview" class="notice">Xem trước: {{number(s.preview.summary.total)}} đăng ký, {{number(s.preview.summary.clevel)}} C-Level, {{number(s.preview.quality.invalidDates)}} khách thiếu ngày hợp lệ. Trường không có được giữ trống.</div><div class="row justify-end"><MButton variant="secondary" :loading="s.busy" @click="run(previewData)">Kiểm tra dữ liệu</MButton><MButton variant="primary" :loading="s.busy" :disabled="!s.preview" @click="run(commitData)">Nhập dữ liệu</MButton></div></div></section></template>
